import React, { useState, useMemo } from "react";
import MatchItem from "./MatchItem";

function MatchList({ matches, selectedLeague, orderedLeagues }) {
  // По умолчанию null, чтобы показывать ВСЕ матчи
  const [selectedDate, setSelectedDate] = useState(null);

  // Генерируем больше дат (Вчера + Сегодня + 14 дней вперед), чтобы заполнить место
  const dateOptions = useMemo(() => {
    const dates = [];
    for (let i = -1; i <= 14; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      dates.push({
        full: d.toISOString().split("T")[0],
        day: d.getDate(),
        weekday: d.toLocaleDateString("ru-RU", { weekday: "short" }),
      });
    }
    return dates;
  }, []);

  // ЛОГИКА ФИЛЬТРАЦИИ
  const filteredMatches = useMemo(() => {
    let result = [...matches];

    // 1. Если выбрана конкретная лига (через хедер), показываем ВСЕ её матчи, игнорируя дату
    if (selectedLeague) {
      return result.filter((m) => m.league === selectedLeague);
    }

    // 2. Если лига не выбрана, но ВЫБРАНА дата в календаре — фильтруем по дате
    if (selectedDate) {
      result = result.filter((m) => m.utcDate.split("T")[0] === selectedDate);
    }

    return result;
  }, [matches, selectedLeague, selectedDate]);

  // ГРУППИРОВКА И СОРТИРОВКА (как в выпадающем списке)
  const groupedMatches = useMemo(() => {
    const groups = {};
    filteredMatches.forEach((match) => {
      const leagueCode = match.league;
      if (!groups[leagueCode]) {
        const leagueObj = orderedLeagues.find(
          (l) => l.code === leagueCode || l.name === leagueCode,
        );
        groups[leagueCode] = {
          name: leagueObj ? leagueObj.name : leagueCode,
          order: orderedLeagues.findIndex(
            (l) => l.code === leagueCode || l.name === leagueCode,
          ),
          matches: [],
        };
      }
      groups[leagueCode].matches.push(match);
    });

    // Сортируем ключи групп согласно порядку в orderedLeagues
    return Object.entries(groups).sort((a, b) => a[1].order - b[1].order);
  }, [filteredMatches, orderedLeagues]);

  return (
    <div className="w-full">
      {/* 1. ПАНЕЛЬ ДАТ (Растянута на всю ширину) */}
      {!selectedLeague && (
        <div className="flex items-center gap-2 mb-10 bg-gray-900/40 p-2 rounded-2xl border border-gray-800 w-full">
          {/* Контейнер дат скроллится, но занимает максимум места */}
          <div className="flex-grow flex gap-2 overflow-x-auto no-scrollbar">
            {/* Кнопка "ВСЕ" для сброса даты */}
            <button
              onClick={() => setSelectedDate(null)}
              className={`flex-shrink-0 flex items-center justify-center px-4 h-14 rounded-xl font-black text-[10px] uppercase transition-all ${
                selectedDate === null
                  ? "bg-red-600 text-white shadow-lg shadow-red-600/20"
                  : "bg-gray-800 text-gray-500 hover:bg-gray-700"
              }`}
            >
              ВСЕ
            </button>

            {dateOptions.map((d) => (
              <button
                key={d.full}
                onClick={() => setSelectedDate(d.full)}
                className={`flex-shrink-0 flex flex-col items-center justify-center min-w-[60px] h-14 rounded-xl transition-all ${
                  selectedDate === d.full
                    ? "bg-red-600 text-white shadow-lg shadow-red-600/20"
                    : "bg-gray-800 text-gray-500 hover:bg-gray-700"
                }`}
              >
                <span className="text-[10px] font-black uppercase leading-none mb-1">
                  {d.weekday}
                </span>
                <span className="text-base font-black leading-none">
                  {d.day}
                </span>
              </button>
            ))}
          </div>

          {/* Календарь ПЕРЕНЕСЕН НАПРАВО */}
          <div className="relative flex-shrink-0 ml-2">
            <input
              type="date"
              className="absolute inset-0 opacity-0 cursor-pointer z-10"
              onChange={(e) => setSelectedDate(e.target.value)}
            />
            <button
              className={`w-14 h-14 flex items-center justify-center rounded-xl transition-colors ${
                selectedDate &&
                !dateOptions.find((d) => d.full === selectedDate)
                  ? "bg-red-600 text-white"
                  : "bg-gray-800 text-gray-500 hover:bg-gray-700"
              }`}
            >
              <svg
                className="w-6 h-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
                />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* 2. СПИСОК МАТЧЕЙ */}
      {groupedMatches.length === 0 ? (
        <div className="text-center py-20">
          <p className="text-gray-700 font-black uppercase tracking-[0.5em] text-sm animate-pulse">
            Загрузка актуальных данных...
          </p>
        </div>
      ) : (
        groupedMatches.map(([code, league]) => (
          <div key={code} className="mb-14">
            {/* Заголовок Лиги */}
            <div className="flex flex-col items-center mb-8">
              <h2 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tighter">
                {league.name}
              </h2>
              {/* УБРАН Matchday 2526. Выводим только если есть реальный номер тура */}
              {league.matches[0].matchday &&
                league.matches[0].matchday < 100 && (
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mt-1">
                    Matchday {league.matches[0].matchday}
                  </span>
                )}
              <div className="w-20 h-1 bg-red-600 mt-2 rounded-full opacity-40"></div>
            </div>

            {/* Сетка матчей (3 столбика на десктопе) */}
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
              {league.matches.map((match) => (
                <MatchItem key={match.id} match={match} />
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

export default MatchList;
